import gzip
from html import escape
from format_lecon import R,paras
S=gzip.open(R/'ressources_ia/aips/fi_fr/33741.txt.gz','rt').read()
def quote(s):return '<blockquote><p>« '+escape(s.strip())+' »</p></blockquote>'
def line(start):
 found=[x for x in S.splitlines() if x.startswith(start)];assert len(found)==1,(start,len(found));return quote(found[0])
def segment(start,end):
 a=S.index(start)+len(start);b=S.index(end,a);return quote(S[a:b])
def window(l):
 body=paras('L’acide tranexamique stabilise le caillot en freinant sa dégradation. La fiche Cyklokapron donne une posologie orale pour une épistaxis prolongée ou récidivante ; elle ne remplace pas la compression, le contrôle local ni la prise en charge d’une hémorragie grave.', 'Présentations, citations AIPS :')+line('Comprimé pelliculé à 500 mg.')+line('Comprimé effervescent à 1000 mg.')+paras('Rubrique épistaxis de la posologie adulte, citation AIPS :')+line('En cas de saignements prolongés ou récidivants,')+paras('Deux comprimés pelliculés ou un comprimé effervescent correspondent ici à un gramme par prise, par voie orale. Ne pas transposer cette posologie à une application intranasale ni à une injection. Ce n’est pas une prescription systématique pour tout petit saignement.', 'Adaptation rénale, citation du tableau AIPS :')+segment('Posologie de Cyklokapron\n','\nPatients âgés')+paras('L’insuffisance rénale sévère figure dans les contre-indications ; ne pas compléter le tableau par une dose inventée.', 'Enfants, citation AIPS :')+line("Chez l'enfant, la posologie sera déterminée")+paras('La fiche donne une dose pondérale mais pas un schéma pédiatrique complet spécifique à l’épistaxis dans cette ligne. Fréquence, durée et adéquation au terrain sont à déterminer par le prescripteur ; le schéma adulte ne doit pas être transposé automatiquement.', 'Contre-indications, citation AIPS :')+segment('\nContre-indications\n','\nMises en garde')+paras('Grossesse et allaitement, citation AIPS :')+segment('\nGrossesse, allaitement\n','\nEffet sur')+paras('Vérifier risque thrombotique, fonction rénale, antécédent convulsif, hématurie haute et traitements concomitants. La fiche avertit du risque d’obstruction urinaire avec une hématurie des voies supérieures et recommande l’arrêt en cas de troubles visuels. Les comprimés effervescents apportent du sodium, à prendre en compte si restriction.', 'La prise d’un anticoagulant n’est pas une raison de prescrire empiriquement un antifibrinolytique ni d’arrêter l’anticoagulant seul. L’équipe apprécie conjointement le mécanisme du saignement, le bénéfice attendu et les contre-indications.')
 return l.subwindow('med13','Cyklokapron oral : indication et sécurité',body,(13,))
